from pathlib import Path
import json
home=Path.home()
state_root=home/".local/state/prediction-project-executor"
campaign=home/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
out={}
for t in [
 "DEV-PRED-A2Z-DIRECT-SOL-REGRESSION-FIX-20261007-N1E33",
 "DEV-PRED-A2Z-ASTRA-PREBUILD-STATUS-20261007-N1E34",
]:
 p=state_root/(t+".json")
 if p.is_file():
  o=json.loads(p.read_text())
  out[t]={"status":o.get("status"),"operation_count":o.get("operation_count"),"completed_at_utc":o.get("completed_at_utc")}
 else:
  out[t]={"status":"MISSING"}
astra="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
p=campaign/"model_results"/(astra+".json")
if p.is_file():
 o=json.loads(p.read_text())
 review={}
 try:
  review=json.loads(o.get("final") or "{}")
 except Exception:
  pass
 out["ASTRA_RESULT"]={"exists":True,"phase":o.get("phase"),"model":o.get("model"),"model_policy":o.get("model_policy"),"decision":review.get("decision")}
else:
 out["ASTRA_RESULT"]={"exists":False}
raise RuntimeError("FINAL_STATUS="+json.dumps(out,sort_keys=True,separators=(",",":")))
